# frozen_string_literal: true

require Rails.root.join("lib/ui_fixtures").to_s
require Rails.root.join("lib/messaging_fixtures").to_s

# The committed files are generated by `rake command_tower:ui:fixtures`
# (rails_app/lib/tasks/ui_fixtures.rake); this keeps the generator reproducible.
# The inbox documents of `rake command_tower:messaging:fixtures` share the directory and are
# checked by `messaging_fixtures_spec.rb`.
RSpec.describe "UI document fixtures", :aggregate_failures do # rubocop:disable RSpec/DescribeClass
  let(:keys) { UiFixtures.keys }
  let(:committed) do
    names = Dir[File.join(UiFixtures::OUTPUT_DIR, "*.json")].map { |file| File.basename(file, ".json") }
    names - MessagingFixtures::DOCUMENTS.keys
  end

  it "defines the CT-built fixture keys" do
    expect(keys).to include("key_value_facts", "code_qr", "header_all", "facts_block", "picks_reminder")
    expect(keys.length).to eq(28)
  end

  it "has a committed file for every fixture and none extra" do
    expect(committed).to match_array(keys)
  end

  it "matches a fresh render of each composer" do
    keys.each do |key|
      expect(File.read(UiFixtures.path(key))).to eq(UiFixtures.json(key)), "#{key} is stale; rerun the generator"
    end
  end

  it "builds valid documents with a text fallback" do
    keys.each do |key|
      expect(UiFixtures.document(key).validation_errors).to be_empty
      expect(JSON.parse(UiFixtures.json(key))["textFallback"]).to be_present
    end
  end
end
